  t("<b>Company State by 1856</b>", "<b>63% of the land, 78% of the people</b>; <b>no annexation after Dalhousie 48-56</b>", "India = Company State + <b>565 Indian States</b>", t("<b>3 instruments of Dalhousie 48-56 (via PoP 1813-58)</b>", "<b>1 Doctrine of Lapse</b>: refuse adopted heirs", "<b>2 Wars</b>: 2nd Anglo-Sikh 1848-49 (<b>Punjab</b>), 2nd Anglo-Burmese 1852-53 (<b>Pegu</b>)", "<b>3 Annexation in Lieu of Subsidy</b>: <b>Berar 1853</b> from Hyderabad"), "Besides: Maritime Ring Fence, modernisation, five-policy framework", w=24),
  bx('pk', "<b>Remember: Dalhousie 48-56 = Lapse, War, Lieu.</b> Teacher: 'annexation of the Indian mainland' = into <b>British India</b>. Logic of Lapse: succession disputes (R v R) → instability → hurts British business → <b>British interests paramount</b>. His other face (future syllabus, Ch 19): <b>Wood's Despatch 1854</b>, Hindu Widow Remarriage Act 1856 (passed under Canning 56-62; Dalhousie only supported), Railways, Post and Telegraph, Canals."),
  tb(["", "Paramountcy of the EIC", "Paramountcy of the Crown"], ["Years", "<b>1813-58</b>, by <b>Francis Hastings 13-23</b>", "<b>1858 to 15 Aug 1947</b>"], ["Meaning", "Company State supreme among all States; British interests first, <b>even annexation</b>; contributed to 3rd Anglo-Maratha War (Ch 13)", "Legal relationship between Crown and <b>Indian Prince</b>, 'not British India' (British India = part ruled by the British)"]),
  bx('ye', "<b>Note:</b> do not mix the two Paramountcies. Board 'Notes of Foundation' with 'MMP': most of the chapter is Foundation, a small part is in the teacher's MMP; the handout gives nothing more."),
  sec("DOCTRINE OF LAPSE " + P('2002') + ' ' + P('2004'), 'r'),
  t("<b>Doctrine of Lapse</b>", "<b>Formulated by Court of Directors, 1847</b>; <b>implemented systematically by Dalhousie 48-56</b>", "No biological heir: <b>rights lapse</b> (= R2: right to rule + right to pension), State annexed into British India", "Hindu law allowed adoption; <b>DoL overrides Hindu law</b>", "<b>Court of Directors</b> = top decision-making body of the EIC, not a Government body", w=22),
  bx('pk', "<b>Prelims (teacher):</b> Formulated = Court of Directors; Implemented = Dalhousie 48-56. 'Author' is only loose speech: <b>choose by the verb</b>. Prelims 2002: Dalhousie 48-56 = Doctrine of Lapse."),
  sec("SEVEN STATES IN SEVEN YEARS 1848-54 " + P('2004'), 'g'),
  tb(["#", "Year", "State", "Present region"], ["1", "1848", "<b>Satara</b> (first Lapse State)", "Maharashtra"], ["2", "1849", "<b>Sambalpur</b>", "Odisha"], ["3", "1849", "<b>Jaitpur</b>", "UP, Bundelkhand"], ["4", "1850", "<b>Baghat</b>", "Himachal Pradesh, small hill State near Solan"], ["5", "1852", "<b>Udaipur</b>", "Chhattisgarh (then Central Provinces)"], ["6", "1853-54", "<b>Jhansi</b>", "Uttar Pradesh"], ["7", "1854", "<b>Nagpur</b>", "Maharashtra"]),
  mn("BHAGAT SAMBHAL, JA JHAdio mein, UDta SA NAG", "<b>Bhagat</b> = Baghat, <b>Sambhal</b> = Sambalpur, <b>Ja</b> = Jaitpur, <b>Jha</b> = Jhansi, <b>Ud</b> = Udaipur, <b>Sa</b> = Satara, <b>Nag</b> = Nagpur. <i>Not date order: use the table for dates.</i>"),
  bx('ye', "<b>Traps:</b> Udaipur 1852 is the small <b>Chhattisgarh</b> State, NOT Mewar (Rajasthan). <b>Awadh 1856 is NOT Lapse</b> (sits apart at the end of the chain). <b>Prelims 2004 order:</b> Satara 1848, Sambalpur 1849, Jhansi 1854 = <b>3, 2, 1</b>. Jhansi: table says 1853-54, flowchart and PYQ say <b>1854</b>: use 1854 for sequences. Flowchart lists Jaitpur before Sambalpur (both 1849): learn table order. Nagpur teacher note: its 1816 alliance (Ch 13)."),
  sec("INAM COMMISSION 1852, NANA SAHIB, BERAR 1853", 'b'),
  t("<b>Inam Commission 1852</b>", "<b>Bombay Presidency</b>; investigated <b>inams</b> (tax-free grants to Brahmins, temples, others)", "Demanded <b>proof of title</b>; insufficient proof = confiscated; <b>about 20,000 estates</b>", "Logic = <b>Lapse applied to land titles</b> (teacher: 'ignore', handout aid; repeated in legitimacy section)", w=22),
  t("<b>Lapse on pensions: Nana Sahib</b>", "<b>Bajirao II 96-18 died 1851</b> (pensioned at <b>Bithur 1819</b> after 3rd Maratha War)", "Dalhousie 48-56 refused the <b>Rs 8 lakh per annum</b> pension to adopted son <b>Nana Sahib</b>", "Argument: adopted sons inherit private wealth, not political titles or State pensions", "Made him a key <b>1857 leader from Bithur</b>", w=22),
  t("<b>Berar 1853</b> (2nd instrument)", "<b>Hyderabad signed the first SA in 1798</b>, paid ever-rising subsidy", "<b>1853 could not pay</b>: Berar annexed as <b>permanent payment</b>", "Same pattern as <b>half of Awadh in 1801</b>: unpaid subsidy becomes territory", w=22),
  sec("ANNEXATION OF AWADH 1856 (six steps) " + P('2008'), 'r'),
  tl(("1765", "<b>Treaty of Allahabad</b> (Clive 57-67): PoIR + PoRF + <b>mini SA</b>"), ("1798", "<b>John Shore 93-98</b> replaces <b>Wazir Ali 97-98</b> with uncle <b>Sadat Ali Khan II</b>: Rs 76 lakh a year + Allahabad fort"), ("1801", "Sadat Ali defaults; <b>Wellesley 98-05</b> (via Henry Wellesley) imposes full SA; <b>half of Awadh</b> (Gorakhpur, Rohilkhand, Doab) annexed = <b>Ceded Districts</b>"), ("1855-56", "Resident = Indirect Rule; Nawab <b>Wajid Ali Shah</b> powerless; <b>1856 rest annexed</b> for maladministration")),
  t("<b>Steps 2 to 5 and teacher's board</b>", "Step 2: EIC gradually raised subsidy demands", "1801 seizure was <b>unjust: revenue twice the subsidy</b>", "Step 5: EIC kept demanding more even after the permanent payment: Nawab raised taxes, <b>peasant revolt threat by 1855</b>; teacher: <b>'Be-SHaram'</b> (shameless)", "<b>Indirect Rule 90 years in Awadh (1765-1855) vs about 7 in Bengal (1765-72)</b>", "1765 = <b>mini / quasi SA</b>: 'X DCFA, X Awadh army = 0, rest yes' (subsidy, EIC army, military alliance = PoRF, Resident)", "<b>Doab</b> = land between two rivers, fertile, high land revenue; Gorakhpur and Rohilkhand with Awadh since 1775", "Wajid Ali Shah: <b>no power but all responsibility</b>", w=26),
  bx('pk', "<b>Prelims 2008:</b> ruler removed on pretext of misgovernance = <b>Awadh (a)</b>. Wajid Ali Shah had heirs, so Lapse could not apply; Jhansi and Nagpur went by Lapse; Satara first, 1848."),
  tb(["Year", "Awadh / UP: administrative status"], ["1801", "<b>Ceded Districts</b> formed from annexed half"], ["1836", "<b>NWP</b> full province (teacher: capital Agra)"], ["1856", "Rest of Awadh annexed (teacher: capital Lucknow)"], ["1877", "'North-Western Provinces and Oudh'"], ["1902", "'United Provinces of Agra and Oudh'"], ["1937", "'United Provinces'"], ["1950", "<b>Uttar Pradesh</b>"], ["2000", "<b>Uttarakhand</b> carved out ('UK + UP')"]),
  bx('ye', "<b>Source note:</b> handout names the Nawab placed in 1798 as Sadat Ali Khan II; Ch 10 gives the formal alliance with Awadh as 1801. The 1765 'PoIR + PoRF + mini SA' is Clive 57-67's chain (Ch 10, 11)."),
  sec("SIKH STATE: IDEAL BUFFER TO TARGET " + P('1995'), 'b'),
  t("<b>Buffer to target</b>", "<b>PoRF</b>: stable, strong, friendly border States (teacher's <b>3 qualities of a buffer</b>). If not achievable: <b>Indirect Rule</b> (Nepal 1814-16, Afghanistan 1839, Punjab 1845) or <b>annexation</b> (Assam + lower Burma 1824-26, Punjab 1849, Burma 1852-53)", "<b>Ranjit Singh 01-39</b> = ideal buffer; <b>1809 Treaty of Amritsar</b> (Sutlej boundary; fear of Russia: Russia → Afghanistan → Punjab → British India)", t("<b>After 1839 factionalism tore it apart</b>", "Royal family succession fights", "<b>Sindhanwaliyas</b> (Jat clan or misl)", "<b>Dogra Rajputs</b> as Wazirs (also rulers of Jammu)", "<b>Khalsa Army</b> (handout: wanted governance by <b>Panchayats</b>, harder to manage than a feudal-loyal army)"), "<b>1838 Tripartite Treaty</b>: EIC aimed PoIR in Afghanistan, puppet <b>Shah Shuja</b> vs Dost Md", "<b>Law of power:</b> power centralises in a strong personality; if he weakens it leaks <b>downward</b> (R v N, R v R, N v N) or goes <b>sideways</b> to a replacer (British, 1849)", w=28),
  tb(["Treaty of Lahore, 9 March 1846 (after 1st Anglo-Sikh War)", "Term"],
     ["1 Military", "<b>Khalsa Army reduced</b>, EIC army stationed; not fully disbanded out of respect for Sikh sentiment (Khalsa founded <b>1699 by Guru Gobind Singh 76-08</b>)"],
     ["2 Territory", "<b>Jalandhar Doab</b> (between Beas and Sutlej) annexed"],
     ["3 Kashmir mechanism", "Darbar could not pay <b>indemnity Rs 1.5 crore</b>: ceded hills between <b>Beas and Indus (Kashmir, Hazara)</b>; EIC <b>sold to Gulab Singh for 75 lakh Nanakshahee rupees</b>; he became Maharaja of J&amp;K under the British; formalised by <b>Treaty of Amritsar, 16 March 1846</b>"],
     ["4 Oversight", "<b>PoIR in Punjab</b>: Resident <b>Henry Lawrence</b> as effective Regent"]),
  bx('bl', "<b>Like Awadh 1765:</b> both 'quasi / mini SA': ruler stays, army cut, EIC army, Resident. <b>Kashmir mechanism:</b> 'took from Punjab, sold to Dogras'. Strategic note: Kashmir sold to reward Gulab Singh's neutrality; <b>legal origin of the Kashmir Question</b>, a Hindu monarchy over a Muslim-majority population."),
  bx('ye', "<b>Three documents:</b> Amritsar <b>1809</b> (Ranjit Singh 01-39 + EIC, Sutlej boundary, PoRF) vs Lahore <b>9 Mar 1846</b> vs Amritsar <b>16 Mar 1846</b> (Kashmir sale; legal foundation of J&amp;K). Lahore is signed 7 days before Amritsar 1846."),
  t("<b>2nd Anglo-Sikh War 1848-49</b>", "<b>Reason:</b> governors of <b>Multan (Mulraj)</b> and <b>Haripur (Chattar Singh)</b> revolted: opportunity for Dalhousie 48-56 (real reason: British interest paramount)", "<b>Punjab annexed</b> from <b>Duleep Singh 43-49</b> (child of 5 at accession)", "<b>Koh-i-Noor</b> surrendered to the British Crown", "<b>Board of Administration</b>: Lawrence Brothers + Charles Mansel", "Last major independent State outside Company State gone; frontier at Afghan foothills (teacher: <b>Khyber Pass</b> entry point)", w=24),
  bx('ye', "<b>Prelims 1995 trap:</b> <b>Chilianwala 1849</b> = 2nd Anglo-Sikh War battle, not 'Dalhousie 48-56 vs Marathas'."),
  sec("BURMA, BAY OF BENGAL AND THE MARITIME RING FENCE", 'g'),
